const { writeFileSync, mkdirSync, existsSync } = await import('node:fs');
const { dirname } = await import('node:path');
const inputPath = process.env.INPUT_PATH;
const outputPath = process.env.OUTPUT_PATH;
if (!inputPath) throw new Error('Missing INPUT_PATH');
if (!outputPath) throw new Error('Missing OUTPUT_PATH');
if (!existsSync(inputPath)) throw new Error('Input file does not exist');
const outDir = dirname(outputPath);
if (!existsSync(outDir)) mkdirSync(outDir, { recursive: true });
globalThis.inputPath = inputPath;
globalThis.outputPath = outputPath;

const mod = await import('docx2pdf-converter');
